mapper.select:
SELECT (p.paid_at AT TIME ZONE 'Asia/Shanghai')::date AS biz_date, count(*) AS txn_count, coalesce(sum(p.amount), 0) AS total_amount, coalesce(sum(p.amount) FILTER (WHERE p.method = '现金'), 0) AS cash_amount, count(*) FILTER (WHERE p.pay_point IS NULL OR btrim(p.pay_point) = '') AS no_point_count, coalesce(sum(p.amount) FILTER (WHERE p.pay_point IS NULL OR btrim(p.pay_point) = ''), 0) AS no_point_amount FROM payment p WHERE p.status = '正常' AND p.paid_at >= #{fromTs} AND p.paid_at < #{toTs}
AND p.community_id = #{communityId}
GROUP BY 1 ORDER BY 1

SELECT (p.paid_at AT TIME ZONE 'Asia/Shanghai')::date AS biz_date, p.pay_point AS pay_point, count(*) AS txn_count, coalesce(sum(p.amount), 0) AS amount FROM payment p WHERE p.status = '正常' AND p.pay_point IS NOT NULL AND btrim(p.pay_point) <> '' AND p.paid_at >= #{fromTs} AND p.paid_at < #{toTs}
AND p.community_id = #{communityId}
GROUP BY 1, 2 ORDER BY 1, 2
